SELECT jsonb_build_object('guildId',guild_id::text,'eventId',event_id::text,'channelId',channel_id::text, 'messageId',CASE WHEN message_id IS NULL THEN NULL ELSE to_jsonb(message_id::text) END,'status',status, 'lastError',last_error,'dateUpdated',to_char(date_updated AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) AS value FROM zc_private.discord_delivery WHERE guild_id=$1 AND event_id=$2
